const DASHES_RE=/[\u2010\u2011\u2012\u2013\u2014\u2212]/g,NON_BREAK_SPACES_RE=/[\u00A0\u202F]/g,ZERO_WIDTH_RE=/[\u200B\u200C\u200D]/g,CLEAN_RE=/[^\wа-яА-ЯёЁ\s\-]/g,SPACE_RE=/\s+/g;function countWordsInNumber(e){if(0===(e=Math.abs(parseInt(e))))return 1;if(e<=20)return 1;if(e<=99)return 2;if(e<=999){let t=1,r=e%100;return r>0&&(t+=countWordsInNumber(r)),t}if(e<=9999){let t=e%1e3,r=countWordsInNumber(Math.floor(e/1e3))+1;return t>0&&(r+=countWordsInNumber(t)),r}if(e<=999999){let t=e%1e3,r=countWordsInNumber(Math.floor(e/1e3))+1;return t>0&&(r+=countWordsInNumber(t)),r}return Math.floor(e.toString().length/2)+2}function countWords(e){if(!e)return 0;const t={"№":"номер",$:"доллар","#":"хэштэг","@":"собака","%":"процент","€":"евро","£":"фунт","¥":"иена","₽":"рубль","°":"градус","=":"равно"};e=(e=(e=(e=e.replace(DASHES_RE,"-")).replace(NON_BREAK_SPACES_RE," ")).replace(ZERO_WIDTH_RE,"")).replace(/([№$#@%€£¥₽°=])/g," $1 ");for(const[r,a]of Object.entries(t)){const t=r.replace(/[.*+?^${}()|[\]\\]/g,"\\$&"),n=new RegExp(`(^|\\s)${t}($|\\s)`,"g");e=e.replace(n,`$1${a}$2`)}return(e=(e=(e=(e=e.replace(/\b\d+([.,]\d+)?\b/g,e=>{const t=countWordsInNumber(e.replace(/[.,]/g,""));return" СЛОВО ".repeat(t).trim()})).replace(/-/g," ")).replace(/[^\wа-яА-ЯёЁ\s]/g," ")).replace(/\s+/g," ").trim()).split(" ").filter(e=>""!==e.trim()).length}function countChars(e){return e?e.replace(/\s/g,"").length:0}function roundToHundred(e,t=500){return Math.max(t,100*Math.floor((parseInt(e)+50)/100))}function calculateTextPrice(e){const t=e/120;let r;return r=t<=8?e*(250/120):e*(200/120),roundToHundred(r)}function calculateVideoPrice(e){let t;return t=(e=Math.ceil(e))<=5?300*e:e<=10?250*e:200*e,t}function calculateTranslateTextPrice(e){return roundToHundred(e/1e3*200)}function calculateTranslateVoicePrice(e){return roundToHundred(150*(e=Math.ceil(e))+calculateVideoPrice(e))}function calculateFacePrice(e){return roundToHundred(4*calculateTextPrice(e),5e3)}function applyUrgentMarkup(e){let t;t=e<=500?1:e<=600?.8:e<=700?.7:e<=800?.6:e<=900||e<=2e3?.5:e<=2100||e<=2200?.45:e<=2500?.4:e<=2700?.35:e<=2900?.32:e<=3e3?.31:e<=4e3?.3:e<=4200||e<=4300?.27:e<=4400?.26:.25;const r=e+Math.floor(e*t);return 100*Math.floor((r+99)/100)}function calculateDeadline(e,t=!1,r=0){let a=new Date;const n=a.getDay(),c=0===n?6:n-1;if(c>=5&&!t){const e=7-c;a.setDate(a.getDate()+e)}if(t&&e<=30){const e=new Date(a);return e.setDate(e.getDate()+1),{days:1,date:formatDate(e),text:`1 день (до ${formatDate(e)} включительно)`}}let l;l=e<=10?1:e<=20?2:e<=30?3:4,l+=r;let u=new Date(a),o=0;for(;o<l;){u.setDate(u.getDate()+1);const e=u.getDay();e>=1&&e<=5&&o++}const i=Math.floor((u-a)/864e5);return{days:i,date:formatDate(u),text:`${i} ${pluralizeDay(i)} (до ${formatDate(u)} включительно)`}}function formatDate(e){return`${String(e.getDate()).padStart(2,"0")}.${String(e.getMonth()+1).padStart(2,"0")}.${e.getFullYear()}`}function pluralizeDay(e){return e%10==1&&e%100!=11?"день":e%10>=2&&e%10<=4&&(e%100<10||e%100>=20)?"дня":"дней"}function getOptimalTiming(e){const t=e*(60/180),r=e*(60/130),a=Math.floor(t/60),n=Math.floor(t%60),c=Math.floor(r/60),l=Math.floor(r%60),u=(e,t)=>`${String(e).padStart(2,"0")}:${String(t).padStart(2,"0")}`;return`${u(a,n)} – ${u(c,l)}`}function calculatePrice(e,t,r=!1){let a=0,n=0,c=0,l=0,u=null,o=null;switch(e){case"voice_text":n=parseInt(t),a=calculateTextPrice(n),l=Math.ceil(n/120),u=calculateDeadline(l,r),o=getOptimalTiming(n);break;case"voice_video":l=parseInt(t),a=calculateVideoPrice(l),u=calculateDeadline(l,r);break;case"translate_text":c=parseInt(t),a=calculateTranslateTextPrice(c),l=c/120,u=calculateDeadline(l,r);break;case"translate_voice":l=parseInt(t),a=calculateTranslateVoicePrice(l),u=calculateDeadline(l,r,3);break;case"voice_camera":n=parseInt(t),a=calculateFacePrice(n),l=Math.ceil(n/120),u=calculateDeadline(l,r),o=getOptimalTiming(n)}return{service:e,wordCount:n,charsCount:c,durationMinutes:l,priceNormal:a,priceUrgent:r?applyUrgentMarkup(a):null,deadline:u,optimalTiming:o,isUrgent:r}}window.PricingCalculator={calculatePrice:calculatePrice,countWords:countWords,countChars:countChars};